import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; public class TestBcrypt { public static void main(String[] args) { BCryptPasswordEncoder enc = new BCryptPasswordEncoder(); System.out.println("Matches 123456 (old): " + enc.matches("123456", "$2a$10$udyqLCXKD1OmyG9W4q70Ge45MHJ0Fbc.FgyLU6IHwXEPqQeBw6IUC")); System.out.println("Matches 123456 (new): " + enc.matches("123456", "$2a$10$T.F92PHJ48QsTBO3AbX06evAdYGW1e./zUr784F/iCZCKuzEGqUAq")); System.out.println("Matches novaSenha123 (new): " + enc.matches("novaSenha123", "$2a$10$T.F92PHJ48QsTBO3AbX06evAdYGW1e./zUr784F/iCZCKuzEGqUAq")); } }
